using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using Newtonsoft.Json;
public static class WallSurvey {public static string Main(){var s=SceneManager.GetActiveScene();var r=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).Where(x=>x.enabled&&x.gameObject.activeInHierarchy&&!x.transform.GetComponentsInParent<Transform>().Any(t=>t.name=="RebuiltArchitectureVisual")&&(x.name.Contains("Wall")||x.name.Contains("Cell")||x.name.Contains("Partition"))).Select(x=>new{name=x.name,path=PathOf(x.transform),size=new[]{x.bounds.size.x,x.bounds.size.y,x.bounds.size.z},position=new[]{x.transform.position.x,x.transform.position.y,x.transform.position.z},mesh=AssetDatabase.GetAssetPath(x.GetComponent<MeshFilter>()?.sharedMesh),materials=x.sharedMaterials.Select(m=>m?AssetDatabase.GetAssetPath(m):"missing").ToArray()}).ToArray();var json=JsonConvert.SerializeObject(new{scene=s.path,playing=EditorApplication.isPlaying,dirty=s.isDirty,walls=r},Formatting.Indented);File.WriteAllText(Path.GetFullPath(Path.Combine(Directory.GetParent(Application.dataPath).FullName,"../../tmp/WallTexturing_20261103/survey.json")),json);return json;}static string PathOf(Transform t)=>t.parent==null?t.name:PathOf(t.parent)+"/"+t.name;}
